<script setup lang="ts">import {Run} from '../types/domain';import {number} from '../utils/format';defineProps<{run:Run}>()</script><template><div class="run-summary"><div><span class="eyebrow">{{run.result.study.code}} / AITCHISON GEOMETRY</span><h3>{{run.result.study.name}}</h3><p>{{run.result.statistics.n}}样本 · {{run.result.statistics.k}}组 · {{run.result.components.length}}成分 · <template v-if="run.result.pairwise?.legacy">工艺对检验未保存（历史运行）</template><template v-else>{{run.result.pairwise?.testable_pairs??0}}个可检验工艺对 / 共{{run.result.pairwise?.pairs_total??0}}对</template></p></div><div><span>组间R² / 全局p</span><b>{{number(run.result.statistics.R2,4)}}</b><small>p {{number(run.result.statistics.p,4)}} / {{run.permutations}}次置换 · 全局p不指出具体工艺对</small></div><div><span>显式零替换</span><b>{{run.delta}}<em> δ</em></b><small>{{run.result.zero_rows}}行含零 / 非零行仅闭合</small></div></div></template>
